import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import {
  LOADING_DOTS_DEFAULT_ARIA_LABEL,
  LOADING_DOTS_DEFAULT_COLOR,
  LOADING_DOTS_DEFAULT_SIZE,
} from './LoadingDots.constants';
import {
  StyledLoadingDot,
  StyledLoadingDotsContainer,
} from './LoadingDots.styles';
import type { LoadingDotsProps } from './LoadingDots.types';

export const LoadingDots = React.forwardRef<HTMLDivElement, LoadingDotsProps>(
  (
    {
      size = LOADING_DOTS_DEFAULT_SIZE,
      color = LOADING_DOTS_DEFAULT_COLOR,
      dataTestId,
      ariaLabel,
      className,
      ...props
    },
    forwardedRef,
  ) => (
    <StyledLoadingDotsContainer
      {...omitTransientProps(props)}
      ref={forwardedRef}
      className={className}
      role="status"
      aria-busy="true"
      aria-label={ariaLabel ?? LOADING_DOTS_DEFAULT_ARIA_LABEL}
      data-testid={dataTestId}
      $size={size}
    >
      <StyledLoadingDot $color={color} $size={size} />
      <StyledLoadingDot $color={color} $size={size} />
      <StyledLoadingDot $color={color} $size={size} />
    </StyledLoadingDotsContainer>
  ),
);

LoadingDots.displayName = 'LoadingDots';
